async function freshQuiescence(){
 const node=fs.realpathSync(process.execPath),live=[],unreadable=[];for(const name of fs.readdirSync('/proc').filter(name=>/^\d+$/.test(name))){const pid=Number(name);if(pid===process.pid)continue;try{if(fs.statSync('/proc/'+pid).uid!==process.getuid())continue;const executable=fs.readlinkSync('/proc/'+pid+'/exe'),cwd=fs.readlinkSync('/proc/'+pid+'/cwd'),argv=fs.readFileSync('/proc/'+pid+'/cmdline','utf8').split('\0').filter(Boolean);if(classifyUi4Application(executable,cwd,argv,node))live.push({pid,executable,cwd,argvSha256:sha(JSON.stringify(argv))})}catch(error){if(['ENOENT','ESRCH'].includes(error.code))continue;const raw=fs.readFileSync('/proc/'+pid+'/comm'),row={pid,code:error.code,comm:raw.toString('utf8').trim(),commRawBytesSha256:sha(raw)},known=[{pid:276,code:'EACCES',comm:'systemd',commRawBytesSha256:'12e6ff4feb1b552a431b41d3935d33f08f9d75ddb8a88f645f4cf231bc05e820'},{pid:278,code:'EACCES',comm:'(sd-pam)',commRawBytesSha256:'8e2daf3d78d113ebf2447fc82d98ba4d9c26a8e3e4fac8ac2d01ee34cbbc1dbd'}];assert(known.some(value=>digest(value)===digest(row)),'Unknown unreadable application cannot become quiescence');unreadable.push(row)}}assert.equal(live.length,0);
 const absent=[];for(const pid of[2064652,2064645,-2064645]){let missing=false;try{process.kill(pid,0)}catch(error){if(error.code==='ESRCH')missing=true;else throw error}assert(missing,'Original PID/group still exists; no process is stopped or adopted');absent.push(pid)}const runtime=createRequire(import.meta.url)('../e2e/runtime.cjs');for(const port of[10070,10071,10080,10090,10091])await runtime.assertPortAvailable(runtime.resolveTarget({mode:'external',baseUrl:'http://127.0.0.1:'+port}));return{kind:'fresh-source-declared-applications-and-original-PID-group-and-five-ports-quiescent',liveApplications:0,unreadable,knownAbsent:absent,fivePortsFree:[10070,10071,10080,10090,10091],sourceApplicationScanIndependentOfCwdForUniqueExecutables:true};
}

