export function validateUi4ObserverSchema(pg,sql){
 assert(sql&&pg.sqlSha256===sha(JSON.stringify(sql)));assert(sql.body.includes("OR TG_TABLE_SCHEMA <> 'poms'"));assert(sql.body.includes("current_database() <> '"+DATABASE+"'"));assert.equal(pg.registration.approvedBodySha256,sha(sql.body));const created=sql.create.filter(statement=>statement.startsWith('CREATE TRIGGER ')),tables=created.map(statement=>{const match=/ AFTER INSERT ON poms\."([a-z0-9_]+)" FOR EACH ROW EXECUTE FUNCTION /.exec(statement);assert(match,'Every observer trigger is declared on the original poms table');return match[1]});assert(tables.length===34&&new Set(tables).size===34);assert.deepEqual(tables,pg.catalogScope.productTables);const relations=pg.installedCatalog.relations.filter(row=>row.nspname==='poms'&&row.relkind==='r'&&tables.includes(row.relname));assert.equal(relations.length,34);assert.deepEqual(relations.map(row=>row.relname).sort(),tables.slice().sort());const registered=pg.installedCatalog.functions.filter(row=>String(row.oid)===String(pg.registration.functionOid));assert.equal(registered.length,1);assert.equal(registered[0].prosrc,sql.body);assert.equal(sha(registered[0].definition),pg.registration.approvedDefinitionSha256);const triggers=pg.installedCatalog.triggers.filter(row=>row.tgname===sql.names.trigger);assert.equal(triggers.length,34);assert.deepEqual(triggers.map(row=>row.relname).sort(),tables.slice().sort());assert(triggers.every(row=>String(row.tgfoid)===String(pg.registration.functionOid)));return tables;
}

